`,r.jsx(o.li,{children:"Polymorphism shows up when overriding functions and variables."}),`
`,r.jsxs(o.li,{children:["Inheritance works with ",r.jsx(o.code,{children:"extends"})," but again only if the parent class is marked ",r.jsx(o.code,{children:"open"}),"."]}),`
`,r.jsxs(o.li,{children:["Abstraction comes into play with interfaces, which let you define ",r.jsx(o.em,{children:"what"})," needs to be done without specifying down ",r.jsx(o.em,{children:"how"})," it’s implemented."]}),`
